<script setup lang="ts">
import { onMounted, ref } from 'vue'; import { api, getData } from '@/api'; import type { Item, Claim, Notice } from '@/types'; import { statusText, typeText, formatTime } from '@/utils/labels'; import { ElMessage, ElMessageBox } from 'element-plus'
const tab = ref('posts'); const posts = ref<Item[]>([]); const mine = ref<Claim[]>([]); const received = ref<Claim[]>([]); const notices = ref<Notice[]>([])
async function load() { [posts.value, mine.value, received.value, notices.value] = await Promise.all([getData<Item[]>(api.get('/items/mine')), getData<Claim[]>(api.get('/claims/mine')), getData<Claim[]>(api.get('/claims/received')), getData<Notice[]>(api.get('/notifications'))]) }
async function process(claim: Claim, approved: boolean) { const { value = '' } = await ElMessageBox.prompt('可填写处理意见或线下核验方式', approved ? '通过认领申请' : '拒绝认领申请', { inputType: 'textarea', confirmButtonText: '确认', cancelButtonText: '取消' }); await api.post(`/claims/${claim.id}/process`, { approved, comment: value }); ElMessage.success('申请已处理'); load() }
async function confirm(claim: Claim) { await ElMessageBox.confirm('确认物品已经线下归还给申请人吗？', '确认归还', { type: 'warning' }); await api.post(`/claims/${claim.id}/confirm-returned`); ElMessage.success('物品已标记为已找回'); load() }
async function readNotice(notice: Notice) { if (!notice.read) { await api.post(`/notifications/${notice.id}/read`); notice.read = true } }
onMounted(load)
</script>
<template><section class="dashboard-page"><div class="page-title"><span class="eyebrow">PERSONAL CENTER</span><h1>个人中心</h1><p>集中管理你的发布、认领进度和站内通知。</p></div><el-tabs v-model="tab" class="dashboard-tabs"><el-tab-pane label="我的发布" name="posts"><el-table :data="posts"><el-table-column label="类型" width="100"><template #default="s">{{ typeText[s.row.postType] }}</template></el-table-column><el-table-column prop="title" label="标题" min-width="220"/><el-table-column prop="location" label="地点"/><el-table-column label="状态" width="100"><template #default="s"><el-tag>{{ statusText[s.row.status] }}</el-tag></template></el-table-column><el-table-column label="审核意见"><template #default="s">{{ s.row.reviewComment || '-' }}</template></el-table-column></el-table></el-tab-pane>
<el-tab-pane label="我的申请" name="mine"><el-table :data="mine"><el-table-column prop="itemTitle" label="物品"/><el-table-column prop="proof" label="认领证明"/><el-table-column label="状态" width="100"><template #default="s">{{ statusText[s.row.status] }}</template></el-table-column><el-table-column prop="handleComment" label="处理意见"/></el-table></el-tab-pane>
<el-tab-pane label="收到的申请" name="received"><el-table :data="received"><el-table-column prop="itemTitle" label="物品"/><el-table-column prop="applicantName" label="申请人"/><el-table-column prop="proof" label="认领证明"/><el-table-column label="操作" min-width="240"><template #default="s"><template v-if="s.row.status === 'PENDING'"><el-button type="success" size="small" @click="process(s.row, true)">通过</el-button><el-button type="danger" size="small" plain @click="process(s.row, false)">拒绝</el-button></template><el-button v-else-if="s.row.status === 'APPROVED'" type="primary" size="small" @click="confirm(s.row)">确认已归还</el-button><span v-else>{{ statusText[s.row.status] }}</span></template></el-table-column></el-table></el-tab-pane>
<el-tab-pane :label="`站内通知（${notices.filter(n => !n.read).length}）`" name="notices"><div class="notice-list"><button v-for="notice in notices" :key="notice.id" :class="['notice-item', { unread: !notice.read }]" @click="readNotice(notice)"><span class="notice-dot"></span><span><b>{{ notice.title }}</b><p>{{ notice.content }}</p><small>{{ formatTime(notice.createdAt) }}</small></span></button><el-empty v-if="!notices.length" description="暂无通知"/></div></el-tab-pane></el-tabs></section></template>
